using J=nlohmann::ordered_json;using K=std::array<int,6>;using P=std::array<int,3>;J read(std::string p){std::ifstream f(p);if(!f)throw std::runtime_error("input");J j;f>>j;return j;}std::string hashfile(std::string p){std::ifstream f(p,std::ios::binary);std::string s{std::istreambuf_iterator<char>(f),{}};unsigned char h[32];SHA256((const unsigned char*)s.data(),s.size(),h);std::ostringstream o;for(auto x:h)o<<std::hex<<std::setw(2)<<std::setfill('0')<<(int)x;return o.str();}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("RUN NEW.json");std::string dir=argv[1];auto c=read(dir+"/casesC/cases.json");auto ca=read(dir+"/auditC.json");J result={{"schema","twist.cost-scale.summary/v1"},{"source_semantic_sha256",ca["semantic_sha256"]},{"input_hashes",J::object()},{"fixtures",J::array()},{"degree_ranges",J::array()},{"streams",J::array()},{"signed_verdict",false}};for(auto&f:c["fixtures"])result["fixtures"].push_back(J{{"p",f["p"]},{"r",f["r"]}});std::map<P,J>cost;for(auto&v:c["runs"])if(!v["trace"].get<std::string>().empty())cost[P{v["fixture"],v["target"],v["method"]}]=v["counts"];
for(int b:{3,5,8,12})for(int method=0;method<2;method++){int lo=1000000,hi=-1,n=0;for(auto&v:c["kernels"])if(v["base_size"]==b&&v["method"]==method&&v["replicate"]==0){int p=v["constructed_field_peak"];lo=std::min(lo,p);hi=std::max(hi,p);n++;}result["degree_ranges"].push_back(J{{"base_size",b},{"method",method},{"inputs",n},{"minimum",lo},{"maximum",hi}});}
for(std::string tag:{"A","B"}){auto a=read(dir+"/audit"+tag+".json");if(a["semantic_sha256"]!=ca["semantic_sha256"]||!a["timings_for_performance"].get<bool>())throw std::runtime_error("semantic mismatch");result["input_hashes"]["audit"+tag]=hashfile(dir+"/audit"+tag+".json");std::map<P,J>p;for(auto&v:a["pipeline_statistics"])p[P{v["fixture"],v["target"],v["method"]}]=v["statistics"];std::map<K,J>k;for(auto&v:a["kernel_statistics"])k[K{v["fixture"],v["target"],v["base_size"],v["sign"],v["sign2"],v["method"]}]=v["statistics"];J stream={{"tag",tag},{"pipeline",J::array()},{"kernel",J::array()},{"by_fixture",J::array()}};
for(int fi=0;fi<4;fi++){double low=1e100,high=0,blow=1e100,bhigh=0;int wins=0;for(int t=0;t<8;t++){J times=J::array(),counts=J::array();for(int m=0;m<4;m++){times.push_back(p.at(P{fi,t,m}));counts.push_back(cost.at(P{fi,t,m}));}double legacy=times[0]["median_ns"],fast=times[2]["median_ns"],generic=times[3]["median_ns"];if(fast<=0)throw std::runtime_error("zero time");double ratio=legacy/fast,br=generic/fast;low=std::min(low,ratio);high=std::max(high,ratio);blow=std::min(blow,br);bhigh=std::max(bhigh,br);wins+=ratio>1;stream["pipeline"].push_back(J{{"fixture",fi},{"target",t},{"cold_time_statistics",times},{"counted_operation_vectors",counts},{"weil_over_fast_tate",ratio},{"plain_bsgs_over_fast_tate",br}});}stream["by_fixture"].push_back(J{{"fixture",fi},{"point_workloads",8},{"cold_fast_tate_wins_vs_weil",wins},{"weil_over_fast_tate_ratio_range",J::array({low,high})},{"plain_bsgs_over_fast_tate_ratio_range",J::array({blow,bhigh})}});}
for(int fi=0;fi<4;fi++)for(int t=0;t<8;t++)for(int b:{3,5,8,12})for(int s:{-1,1})for(int z:{-1,1}){J times=J::array();for(int m=0;m<3;m++)times.push_back(k.at(K{fi,t,b,s,z,m}));double legacy=times[0]["median_ns"],fast=times[1]["median_ns"],external=times[2]["median_ns"];if(fast<=0)throw std::runtime_error("zero kernel time");stream["kernel"].push_back(J{{"fixture",fi},{"target",t},{"base_size",b},{"sign",s},{"sign2",z},{"statistics",times},{"legacy_over_terminal",legacy/fast},{"NTL_over_terminal",external/fast}});}result["streams"].push_back(stream);}
std::ifstream old(argv[2]);if(old.good())throw std::runtime_error("fresh output");std::ofstream out(argv[2]);out<<result.dump()<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 101;}}
